CREATE TABLE comprobantes_pension (id INT UNSIGNED NOT NULL AUTO_INCREMENT,perfil_id INT UNSIGNED NOT NULL,titulo VARCHAR(160) NOT NULL,archivo CHAR(68) NOT NULL,sha256 CHAR(64) NOT NULL,bytes INT UNSIGNED NOT NULL,lectura LONGTEXT NOT NULL,actor_id INT UNSIGNED NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),UNIQUE KEY pension_pdf_unico(perfil_id,sha256),CONSTRAINT pension_pdf_perfil_fk FOREIGN KEY(perfil_id) REFERENCES perfiles_renta(id),CONSTRAINT pension_pdf_json CHECK(JSON_VALID(lectura))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
